@import "pretendard/dist/web/variable/pretendardvariable.css";

.prism-admin-chat-logs {container:prism-chat-logs/inline-size;min-width:0;--prism-admin-table-min-width:980px;}
.prism-admin-chat-logs .prism-admin-header {height:64px;min-height:64px;padding:8px 20px;justify-content:flex-start;}
.prism-admin-chat-logs .prism-admin-header h1 {font-size:18px;font-weight:600;line-height:25px;}
.prism-chat-log-filter {display:flex;justify-content:space-between;align-items:flex-end;gap:20px;padding:20px;border:1px solid var(--prism-control-border);border-radius:12px;min-width:0;}
.prism-chat-log-filter-fields {display:grid;grid-template-columns:160px 303px 250px;gap:20px;min-width:0;}
.prism-chat-log-filter-actions {display:flex;gap:6px;flex-shrink:0;}
.prism-chat-log-dates {padding:0;margin:0;border:0;min-width:0;}
.prism-chat-log-dates>legend {padding:0;margin-bottom:8px;font-size:14px;font-weight:600;line-height:20px;}
.prism-chat-log-dates>div {display:grid;grid-template-columns:minmax(0,1fr) 7px minmax(0,1fr);gap:4px;align-items:center;}
.prism-chat-log-dates .prism-field {position:relative;gap:0;}
.prism-chat-log-dates .prism-field>label {position:absolute;left:0;top:0;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;}
.prism-chat-log-summary {font-size:14px;font-weight:500;color:#363636;}
.prism-chat-log-id {display:flex;align-items:center;width:100%;gap:8px;}
.prism-chat-log-id>span {min-width:0;overflow-wrap:anywhere;}
.prism-chat-log-id>button {display:inline-flex;flex-shrink:0;margin-left:auto;padding:0;border:0;background:none;color:var(--prism-neutral-400);cursor:pointer;}
.prism-chat-log-id>button:disabled {cursor:default;opacity:.5;}
.prism-chat-log-error[data-error] {color:#ea002c;}
.prism-chat-log-subject {display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;}
.prism-admin-chat-logs .prism-directory td:nth-child(6)>.prism-button {padding:0;min-width:0;max-width:100%;height:auto;font-weight:400;justify-content:flex-start;}
.prism-chat-log-empty {display:flex;align-items:center;justify-content:center;min-height:340px;}
.prism-chat-log-copy-notice {position:fixed;z-index:40;bottom:20px;left:20px;max-width:calc(100vw - 40px);}
.prism-chat-log-detail {display:flex;flex-direction:column;height:100%;min-height:0;min-width:0;background:var(--prism-base);}
.prism-chat-log-detail>header {display:flex;flex-direction:column;gap:2px;padding:8px 20px;height:64px;min-height:64px;border-bottom:1px solid var(--prism-border);}
.prism-chat-log-detail>header>nav {display:flex;align-items:center;gap:8px;font-size:14px;font-weight:500;line-height:20px;min-width:0;color:var(--prism-sub);}
.prism-chat-log-detail>header>nav>span {min-width:0;white-space:nowrap;}
.prism-chat-log-detail>header>nav>span:last-child {overflow:hidden;text-overflow:ellipsis;color:#4f5869;}
.prism-chat-log-detail>header>nav>span+span::before {content:"";display:inline-block;width:1px;height:16px;margin-right:8px;vertical-align:middle;background:var(--prism-border);}
.prism-chat-log-detail>header>div {display:flex;align-items:center;gap:8px;min-width:0;}
.prism-chat-log-detail h1 {margin:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;font-size:18px;font-weight:600;line-height:25px;color:#1f1f1f;}
.prism-chat-log-detail>header button {display:inline-flex;flex-shrink:0;align-items:center;justify-content:center;width:20px;height:20px;padding:0;border:0;background:none;color:#28293f;cursor:pointer;}
.prism-chat-log-detail-body {display:flex;flex-direction:column;flex:1;min-height:0;overflow:auto;}
.prism-chat-log-detail-content {width:100%;max-width:900px;margin:0 auto;padding:24px;}
@container prism-chat-logs (max-width:980px) {.prism-chat-log-filter {flex-wrap:wrap;}.prism-chat-log-filter-fields {grid-template-columns:minmax(130px,160px) minmax(240px,303px) minmax(160px,250px);width:100%;}.prism-chat-log-filter-actions {margin-left:auto;}}
@container prism-chat-logs (max-width:700px) {.prism-chat-log-filter-fields {grid-template-columns:minmax(0,1fr);}.prism-chat-log-dates>div {grid-template-columns:minmax(0,1fr) 7px minmax(0,1fr);}}
@media(max-width:480px) {.prism-chat-log-detail-content {padding:16px;}.prism-chat-log-detail>header>nav {font-size:12px;}.prism-chat-log-copy-notice {left:16px;bottom:16px;max-width:calc(100vw - 32px);}}

/* Position-block criteria retain source dimensions; narrow containers stack groups and keep tables scrollable. */
.prism-admin-blocks {container:prism-blocks/inline-size;min-width:0;}
.prism-admin-blocks .prism-admin-header {height:64px;min-height:64px;padding:8px 20px;justify-content:flex-start;}
.prism-admin-blocks .prism-admin-header h1 {font-size:18px;font-weight:600;line-height:25px;}
.prism-admin-blocks .prism-admin-body {padding:0;gap:0;min-width:0;}
.prism-admin-blocks .prism-admin-content {min-width:0;}
.prism-block-content {display:flex;flex-direction:column;gap:20px;padding:20px 40px;min-width:0;}
.prism-block-section {display:flex;flex-direction:column;gap:12px;padding:20px 0;min-width:0;}
.prism-block-section>header {display:flex;align-items:center;justify-content:space-between;gap:12px;padding-bottom:10px;border-bottom:1px solid var(--prism-border);}
.prism-block-section h3 {margin:0;font-size:14px;font-weight:600;line-height:1.4;min-width:0;}
.prism-block-section h3>span {margin-left:6px;color:var(--primary);}
.prism-block-tags {display:flex;flex-wrap:wrap;gap:8px;min-width:0;}
.prism-block-category-grid {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;}
.prism-block-category {display:flex;flex-direction:column;gap:10px;padding:14px 16px;border:1px solid var(--prism-border);border-radius:8px;background:var(--prism-base);min-width:0;}
.prism-block-category h4 {margin:0;font-size:13px;font-weight:600;line-height:1.4;overflow-wrap:anywhere;}
.prism-block-loading {display:grid;gap:20px;}
.prism-block-dialog {max-width:calc(100vw - 32px);}
.prism-block-dialog>.prism-dialog-body>p:first-child {position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;}
.prism-block-dialog .prism-dialog-body {min-width:0;gap:16px;}
.prism-block-form {display:flex;flex-direction:column;gap:20px;min-width:0;}
.prism-block-field {display:flex;flex-direction:column;gap:8px;min-width:0;}
.prism-block-field h3 {margin:0;font-size:14px;font-weight:600;line-height:20px;}
.prism-block-field h3>span {margin-left:2px;color:var(--danger);}
.prism-block-helper {margin:0;font-size:12px;line-height:1.5;color:var(--prism-caption);overflow-wrap:anywhere;}
.prism-block-check {display:flex;align-items:center;gap:6px;padding:6px 12px;margin:8px 0 0;border-radius:6px;background:var(--prism-neutral-50);font-size:13px;line-height:1.5;color:var(--prism-sub);}
.prism-block-check svg {flex-shrink:0;}
.prism-block-check[data-status="checking"] {background:#dceeff;color:#363636;}
.prism-block-check[data-status="available"] {background:#d4f3f1;color:#363636;}
.prism-block-check[data-status="duplicate"],.prism-block-check[data-status="error"] {background:#fff0f0;color:#ea002c;}
.prism-block-generate {display:flex;flex-direction:column;align-items:flex-start;gap:8px;width:100%;}
.prism-block-generate>p {display:flex;align-items:center;gap:6px;width:100%;padding:6px 10px;margin:0;border-radius:4px;background:#fff0f0;font-size:12px;font-weight:500;line-height:1.5;color:#ea002c;}
.prism-block-generate>p svg {flex-shrink:0;}
.prism-textarea-overlay-area,.prism-block-generate-area {position:relative;display:flex;flex-direction:column;gap:8px;min-width:0;}
.prism-block-generation-overlay {position:absolute;inset:0;z-index:1;display:flex;align-items:center;justify-content:center;}
.prism-block-generation-overlay::before {content:"";position:absolute;inset:0;background:var(--prism-base);opacity:.6;}
.prism-block-generation-overlay>.prism-icon {position:relative;}
.prism-block-generation-overlay[data-empty] {position:static;height:48px;}
@media(prefers-reduced-motion:reduce) {.prism-block-generation-overlay>.prism-icon {animation:none!important;}}
.prism-block-sub-jobs {display:flex;flex-direction:column;gap:8px;}
.prism-block-sub-job {display:flex;align-items:flex-start;gap:12px;padding:16px;border:1px solid var(--prism-control-border);border-radius:12px;background:white;min-width:0;}
.prism-block-sub-job>div {display:flex;flex:1;flex-direction:column;gap:6px;min-width:0;}
.prism-block-sub-job .prism-field {display:grid;grid-template-columns:64px minmax(0,1fr);align-items:center;gap:8px;}
.prism-block-sub-job .prism-field>label {font-size:12px;font-weight:400;color:var(--prism-sub);}
.prism-block-sub-job-delete {flex-shrink:0;padding:4px 0;border:0;background:none;font-size:12px;font-weight:500;color:#e45858;cursor:pointer;}
.prism-block-sub-job-delete:hover {text-decoration:underline;}
.prism-block-sub-job-delete:focus-visible {outline:2px solid var(--primary);outline-offset:2px;}
.prism-block-sub-job-delete:disabled {cursor:default;opacity:.5;}
.prism-block-confirm {display:flex;flex-direction:column;gap:16px;min-width:0;min-height:0;}
.prism-block-confirm>p:not(.prism-block-helper) {margin:0;font-size:14px;line-height:1.6;}
.prism-block-dialog .prism-table-scroll {position:relative;}
.prism-block-dialog caption {position:absolute;left:0;top:0;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;}
.prism-block-summary {display:grid;grid-template-columns:1fr 1fr;border:1px solid var(--prism-border);border-radius:6px;background:var(--prism-neutral-50);min-width:0;}
.prism-block-summary>div {display:flex;flex-direction:column;gap:4px;padding:12px 16px;min-width:0;overflow-wrap:anywhere;}
.prism-block-summary>div+div {border-left:1px solid var(--prism-border);}
.prism-block-summary span {font-size:12px;color:var(--prism-sub);}
.prism-block-summary strong {font-size:14px;font-weight:600;}
.prism-block-delete-dialog .prism-dialog-body {height:480px;min-height:0;}
.prism-block-remap-table {overflow:auto;min-width:0;min-height:0;flex:1;}
.prism-block-remap-table table {min-width:660px;table-layout:fixed;}
.prism-block-remap-table th:nth-child(1) {width:140px;}
.prism-block-remap-table th:last-child {width:180px;}
.prism-block-remap-table td:last-child {padding:6px 10px;}
.prism-block-remap-table .prism-field {position:relative;}
.prism-block-remap-table .prism-field>label {position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;}
.prism-block-remap-table:has(th:nth-child(5)) table {min-width:760px;}
.prism-block-remap-table:has(th:nth-child(5)) th:nth-child(3) {width:80px;}
.prism-block-remap-table:has(th:nth-child(5)) th:nth-child(4) {width:170px;}
[data-prism="light"] .prism-criteria-tag {max-width:100%;min-width:0;}
[data-prism="light"] .prism-criteria-tag>button:first-child {min-width:0;}
[data-prism="light"] .prism-criteria-tag small,[data-prism="light"] .prism-criteria-delete {flex-shrink:0;}
.prism-criteria-tag-name {overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;}
[data-prism="light"] .prism-criteria-tag:not(:has(.prism-criteria-delete)) {padding-right:8px;}
[data-prism="light"] .prism-criteria-tag>button:disabled {cursor:default;}
[data-prism="light"] .prism-criteria-tag:has(>button:first-child:not(:disabled):hover) {border-color:#b8c2da;background:#f7f9fd;}
[data-prism="light"] .prism-criteria-tag>.prism-criteria-delete {color:var(--prism-neutral-400);}
[data-prism="light"] .prism-criteria-tag>.prism-criteria-delete:hover {color:#222222;}
@media(prefers-reduced-motion:reduce) {.prism-block-check>.prism-icon {animation:none!important;}}
@container prism-blocks (max-width:760px) {.prism-block-content {padding:20px;} .prism-block-category-grid {grid-template-columns:repeat(2,minmax(0,1fr));}}
@container prism-blocks (max-width:480px) {.prism-block-content {padding:16px;} .prism-block-category-grid {grid-template-columns:minmax(0,1fr);}}
@media(max-width:480px) {.prism-block-sub-job {padding:12px;gap:8px;} .prism-block-sub-job .prism-field {grid-template-columns:minmax(0,1fr);gap:4px;} .prism-block-summary>div {padding:10px;} .prism-block-dialog>footer {padding:16px;flex-wrap:wrap;} .prism-block-delete-dialog .prism-dialog-body {height:min(480px,calc(100dvh - 220px));}}

/* Company-group and notice management share source admin geometry, with separate filter layouts. */
.prism-admin-lists {container:prism-admin-lists/inline-size;min-width:0;--prism-admin-table-min-width:940px;}
.prism-admin-notices {--prism-admin-table-min-width:1100px;}
.prism-admin-lists .prism-admin-header {height:64px;min-height:64px;padding:8px 20px;justify-content:flex-start;}
.prism-admin-lists .prism-admin-header>div {display:grid;gap:2px;min-width:0;}
.prism-admin-lists .prism-admin-header h1 {font-size:18px;font-weight:600;line-height:25px;color:#1f1f1f;}
.prism-admin-lists .prism-admin-filters {display:block;min-width:0;}
.prism-admin-list-filter {display:flex;justify-content:space-between;align-items:flex-end;gap:20px;width:100%;min-width:0;padding:20px;border:1px solid var(--prism-cool-200);border-radius:12px;}
.prism-admin-group-fields {display:grid;grid-template-columns:140px 140px 436px;gap:20px;min-width:0;}
.prism-admin-notice-filter-stack {display:flex;flex-direction:column;gap:20px;min-width:0;}
.prism-admin-notice-fields {display:grid;grid-template-columns:120px 120px 275px 275px;gap:20px;min-width:0;}
.prism-admin-notice-keyword {width:250px;max-width:100%;}
.prism-admin-list-filter-actions {display:flex;gap:6px;flex-shrink:0;}
.prism-admin-list-summary {display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:14px;font-weight:500;min-width:0;}
.prism-admin-list-summary>span {white-space:nowrap;}
.prism-admin-list-summary>span:nth-child(3) {color:var(--prism-sub);}
.prism-admin-list-error {display:flex;align-items:center;gap:12px;overflow-wrap:anywhere;}
.prism-admin-page-sort-note {margin:0 0 6px;font-size:12px;line-height:1.5;color:var(--prism-sub);}
.prism-admin-list-date {border:0;padding:0;margin:0;min-width:0;}
.prism-admin-list-date>legend {margin-bottom:8px;padding:0;font-size:14px;font-weight:600;line-height:20px;}
.prism-admin-list-date>div {display:grid;grid-template-columns:minmax(0,1fr) 7px minmax(0,1fr);align-items:center;gap:4px;}
.prism-admin-list-date .prism-field>label {position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;}
.prism-admin-list-date .prism-field {gap:0;}
.prism-admin-list-date .prism-date-input {min-width:0;}
.prism-admin-notice-empty {display:flex;flex-direction:column;align-items:center;justify-content:center;gap:20px;min-height:400px;}
@container prism-admin-lists (max-width:1088px) {
    .prism-admin-notices .prism-admin-list-filter {flex-wrap:wrap;}
    .prism-admin-notice-filter-stack {width:100%;}
    .prism-admin-notice-fields {grid-template-columns:repeat(2,minmax(0,1fr));}
    .prism-admin-notices .prism-admin-list-filter-actions {margin-left:auto;}
}
@container prism-admin-lists (max-width:1000px) {
    .prism-admin-list-filter {flex-wrap:wrap;}
    .prism-admin-group-fields {grid-template-columns:repeat(3,minmax(0,1fr));width:100%;}
    .prism-admin-list-filter-actions {margin-left:auto;}
}
@container prism-admin-lists (max-width:620px) {
    .prism-admin-list-filter {padding:16px;gap:16px;}
    .prism-admin-group-fields {grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;}
    .prism-admin-group-fields>.prism-field:last-child {grid-column:1 / -1;}
    .prism-admin-notice-fields {gap:16px;}
    .prism-admin-list-date {grid-column:1 / -1;}
    .prism-admin-lists .prism-admin-toolbar {flex-wrap:wrap;}
}
@container prism-admin-lists (max-width:380px) {
    .prism-admin-group-fields,.prism-admin-notice-fields {grid-template-columns:minmax(0,1fr);}
    .prism-admin-list-date>div {grid-template-columns:minmax(0,1fr);gap:8px;}
    .prism-admin-list-date>div>span {display:none;}
    .prism-admin-list-date .prism-field>label {position:static;width:auto;height:auto;margin:0;clip-path:none;white-space:normal;}
    .prism-admin-list-date .prism-field {gap:4px;}
}

/* Position administration: source desktop dimensions, container-sized filter wrapping. */
.prism-admin-positions {container:prism-positions/inline-size;min-width:0;--prism-admin-table-min-width:1100px;}
.prism-admin-positions .prism-admin-header {height:64px;min-height:64px;padding:8px 20px;justify-content:flex-start;}
.prism-admin-positions .prism-admin-header>div {display:grid;gap:2px;min-width:0;}
.prism-admin-positions .prism-admin-header h1 {font-size:18px;font-weight:600;line-height:25px;color:#1f1f1f;}
.prism-admin-positions .prism-admin-body {display:block;padding:0;}
.prism-admin-positions .prism-tabs-content {margin-top:0;}
.prism-position-content {display:flex;flex-direction:column;gap:16px;min-width:0;padding:20px 40px;}
.prism-position-filter-bar {display:flex;justify-content:space-between;align-items:flex-end;gap:20px;min-width:0;width:100%;padding:20px;border:1px solid var(--prism-cool-200);border-radius:12px;}
.prism-position-filter-fields {display:grid;grid-template-columns:140px 140px 140px 200px 140px;gap:20px;min-width:0;}
.prism-position-filter-fields[data-source="TEMP"] {grid-template-columns:140px 140px 120px 140px 140px 140px;}
.prism-position-filter-fields>.prism-field:has(.prism-position-keyword) {grid-column:1 / span 2;}
.prism-position-filter-actions {display:flex;gap:6px;flex-shrink:0;}
.prism-position-toolbar {display:flex;align-items:center;justify-content:space-between;gap:12px;min-width:0;}
.prism-position-list-summary {display:flex;align-items:center;gap:6px;font-size:14px;font-weight:500;min-width:0;}
.prism-position-list-summary>span {white-space:nowrap;}
.prism-position-list-summary>span:nth-child(3) {color:var(--prism-sub);}
.prism-position-sync {display:flex;align-items:flex-start;justify-content:space-between;gap:16px;min-width:0;}
.prism-position-sync-info {display:flex;flex-direction:column;gap:4px;flex:1 1 auto;min-width:0;}
.prism-position-sync-info p {margin:0;font-size:13px;line-height:1.5;color:var(--prism-sub);overflow-wrap:anywhere;}
.prism-position-sync>.prism-button {flex-shrink:0;}
.prism-position-sync-label {display:inline-flex;align-items:center;gap:6px;font-size:14px;font-weight:600;line-height:1.4;}
.prism-position-sync-label>i {width:8px;height:8px;border-radius:50%;flex-shrink:0;background:var(--prism-secondary);}
.prism-position-sync-label[data-status="scheduled"]>i {background:#FBBC05;}
.prism-position-sync-label[data-status="running"]>i {background:#0072C6;}
.prism-position-sync-label[data-status="synced"]>i {background:#009A93;}
.prism-position-sync-label[data-status="failed"]>i {background:#EA002C;}
.prism-position-error {display:flex;align-items:center;gap:12px;overflow-wrap:anywhere;}
@container prism-positions (max-width:1200px) {
    .prism-position-filter-fields[data-source="TEMP"] {grid-template-columns:repeat(3,minmax(0,1fr));flex:1;}
    .prism-position-filter-bar:has([data-source="TEMP"]) {flex-wrap:wrap;}
}
@container prism-positions (max-width:1120px) {
    .prism-position-filter-bar {flex-wrap:wrap;}
    .prism-position-filter-fields {grid-template-columns:repeat(3,minmax(0,1fr));width:100%;flex:1 1 100%;}
    .prism-position-filter-fields[data-source="TEMP"] {flex:1 1 100%;}
    .prism-position-filter-actions {margin-left:auto;}
}
@container prism-positions (max-width:620px) {
    .prism-position-content {padding:16px;}
    .prism-position-filter-bar {padding:16px;gap:16px;}
    .prism-position-filter-fields,.prism-position-filter-fields[data-source="TEMP"] {grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;}
    .prism-position-list-summary {flex-wrap:wrap;}
    .prism-position-sync {flex-wrap:wrap;}
}
@container prism-positions (max-width:380px) {
    .prism-position-filter-fields,.prism-position-filter-fields[data-source="TEMP"] {grid-template-columns:minmax(0,1fr);}
    .prism-position-filter-fields>.prism-field:has(.prism-position-keyword) {grid-column:auto;}
    .prism-position-toolbar {flex-wrap:wrap;}
}

/* Administrator list geometry; generic directory and other AdminLayout callers keep their contracts. */
.prism-admin-users {container:prism-users/inline-size;min-width:0;--prism-user-active:#009A93;--prism-user-inactive:#363636;--prism-admin-table-min-width:940px;}
.prism-admin-users .prism-admin-header {height:64px;min-height:64px;padding:8px 20px;justify-content:flex-start;align-items:center;}
.prism-admin-users .prism-admin-header>div {display:grid;gap:2px;min-width:0;}
.prism-admin-users .prism-admin-header h1 {font-size:18px;font-weight:600;line-height:25px;color:#1f1f1f;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
