.candidate-profile-print .prism-survey-track {margin-bottom:4pt;}
.candidate-profile-print .prism-survey-average {height:.75pt;}
.candidate-profile-print .prism-survey-bar>span {font-size:10pt;}
.prism-mgmt-comments {display:flex;flex-direction:column;gap:16px;padding-bottom:36px;container-type:inline-size;min-width:0;}
.prism-mgmt-section-header {display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px;min-width:0;}
.prism-mgmt-section-header>h3 {margin:0;font-size:14px;font-weight:600;line-height:1.4;overflow-wrap:anywhere;}
.prism-mgmt-section-header>h3>span {color:var(--prism-blue-300);}
.prism-mgmt-card-list,.prism-mgmt-record {display:flex;flex-direction:column;gap:12px;min-width:0;}
.prism-mgmt-card,.prism-ceo-form {display:flex;flex-direction:column;padding:16px;border:1px solid var(--prism-control-border);border-radius:12px;background:white;white-space:pre-line;min-width:0;break-inside:avoid;}
.prism-mgmt-card>header {display:flex;align-items:baseline;gap:8px;margin-bottom:12px;flex-wrap:wrap;min-width:0;}
.prism-mgmt-card h4 {margin:0;font-size:16px;font-weight:700;line-height:1.4;color:var(--prism-primary);overflow-wrap:anywhere;}
.prism-mgmt-year {font-size:14px;font-weight:500;line-height:1.4;color:var(--prism-sub);}
.prism-mgmt-author {margin:0 0 4px;font-size:14px;font-weight:600;line-height:1.4;color:var(--foreground);overflow-wrap:anywhere;}
.prism-mgmt-text {margin:0;white-space:pre-line;font-size:14px;font-weight:400;line-height:1.4;color:#363636;overflow-wrap:anywhere;}
.prism-mgmt-actions {display:flex;align-items:center;justify-content:flex-end;gap:4px;margin-top:12px;}
.prism-mgmt-actions>button {display:inline-flex;width:20px;height:20px;padding:0;border:0;background:none;cursor:pointer;color:var(--foreground);}
.prism-mgmt-actions>button:disabled {cursor:default;color:#9da3b3;}
.prism-mgmt-actions>button:disabled>.prism-icon {color:#9da3b3;}
.prism-mgmt-empty {display:flex;justify-content:center;padding:16px;}
.prism-ceo-form {gap:12px;container-type:inline-size;}
.prism-ceo-form-title {margin:0;font-size:14px;font-weight:600;line-height:1.4;color:var(--foreground);}
.prism-ceo-form-grid {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 12px;min-width:0;}
.prism-ceo-field {display:flex;align-items:center;gap:8px;min-width:0;}
.prism-ceo-field[data-wide] {grid-column:1/-1;}
.prism-ceo-field[data-top] {align-items:flex-start;}
.prism-ceo-field[data-top]>.prism-ceo-label {padding-top:8px;}
.prism-ceo-label {flex:none;width:32px;font-size:12px;font-weight:500;line-height:1.4;color:var(--foreground);}
.prism-ceo-field>.prism-field {flex:1;min-width:0;gap:0;}
.prism-ceo-field .prism-field>label {position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;}
.prism-ceo-textarea {width:100%;min-width:0;min-height:112.625px;padding:6px 12px;font-size:14px;font-weight:500;line-height:1.4375;resize:vertical;}
.prism-ceo-textarea[data-auto-size] {resize:none;}
.prism-ceo-form-footer {display:flex;justify-content:flex-end;}
.prism-mgmt-comments>.prism-toast .prism-button {color:white;}
@container (max-width:480px) {.prism-ceo-form-grid {grid-template-columns:minmax(0,1fr);}}
@container (max-width:220px) {.prism-mgmt-section-header {flex-wrap:wrap;}}
@container (max-width:600px) {
    [data-prism="light"] .prism-candidate-list>.prism-candidate-filters {flex-wrap:wrap;gap:12px;}
    [data-prism="light"] .prism-candidate-list>.prism-candidate-filters>div:first-child {flex-basis:100%;}
    [data-prism="light"] .prism-candidate-collection .prism-candidate-grid {grid-template-columns:repeat(2,minmax(0,1fr));}
    .prism-candidate-toolbar {flex-wrap:wrap;gap:10px;}
    .prism-candidate-toolbar-info {flex-wrap:wrap;gap:8px;}
}
@container (max-width:600px) {
    [data-prism="light"] .prism-candidate-filters>div:first-child {flex-basis:100%;}
}
@container (max-width:360px) {
    [data-prism="light"] .prism-candidate-list>.prism-candidate-filters>div:first-child {grid-template-columns:minmax(0,1fr);}
    [data-prism="light"] .prism-candidate-filters>div:first-child {grid-template-columns:minmax(0,1fr);}
    [data-prism="light"] .prism-candidate-collection .prism-candidate-grid {grid-template-columns:minmax(0,1fr);}
    .prism-candidate-summary {flex-wrap:wrap;}
    .prism-candidate-toolbar-actions {flex-wrap:wrap;}
    .prism-candidate-list {padding-top:16px;}
}

/* Responsive/sizing extensions retain the desktop PRISM baseline. */
.prism-panel[data-compact][data-open]:not([data-expanded]) {width:100%;}
.prism-panel[data-resizing],.prism-panel[data-resizable] {transition:none;}
.prism-panel-placeholder[data-compact] {width:0;}
.prism-panel-content {container-type:inline-size;container-name:prism-content;}
.prism-panel-resizer {position:absolute;left:0;top:0;bottom:0;z-index:2;width:8px;cursor:col-resize;touch-action:none;user-select:none;background:transparent;}
.prism-panel-resizer::after {content:"";position:absolute;top:calc(50% - 18px);left:3px;width:2px;height:36px;border-radius:2px;background:var(--prism-control-border);}
.prism-panel-resizer:hover::after,.prism-panel-resizer:focus-visible::after {background:var(--prism-blue-300);}
.prism-workspace {container-type:inline-size;container-name:prism-shell;}
.prism-workspace-header>strong {min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.prism-workspace[data-compact] .prism-workspace-header {padding:12px;height:auto;min-height:64px;flex-wrap:wrap;}
.prism-workspace[data-compact] .prism-workspace-header>.prism-help {font-size:11px;}
.prism-mobile-navigation {display:flex;flex-direction:column;width:280px;max-width:calc(100vw - 16px);padding:0;overflow:hidden;}
.prism-mobile-navigation>header {height:52px;flex:none;display:flex;align-items:center;justify-content:space-between;padding:8px 12px;border-bottom:1px solid var(--prism-border);}
.prism-mobile-navigation>header h2 {font-size:16px;}
.prism-mobile-navigation>div {flex:1;min-height:0;}
.prism-mobile-navigation .prism-sidebar {width:100%;height:100%;}
.prism-pdf {container-type:inline-size;container-name:prism-pdf;}
.prism-pdf-viewport {display:block;}
.prism-pdf-viewport canvas {display:block;margin-inline:auto;}
@container prism-pdf (max-width:520px) {.prism-pdf-toolbar {display:flex;flex-wrap:wrap;justify-content:space-between;padding:10px;gap:8px;}.prism-pdf-toolbar>:last-child {margin-left:auto;}}
@container prism-shell (max-width:640px) {.prism-workspace-messages,.prism-workspace-list {padding:16px;}.prism-workspace-composer {padding:12px;}.prism-chat-welcome {margin:30px auto;}}
@container prism-content (max-width:520px) {.prism-summary-badge {flex-direction:column;align-items:center;}.prism-summary-badge>div:last-child {border-left:0;border-top:1px solid var(--prism-border);width:100%;}.prism-favorite-photo {width:88px;min-width:88px;height:88px;}.prism-date-fields {flex-wrap:wrap;}.prism-date-fields>.prism-field {flex-basis:100%;}}
@media (max-width:480px) {.prism-dialog {max-width:calc(100vw - 24px);max-height:calc(100dvh - 24px);}.prism-dialog-body {padding:16px;}.prism-dialog>header,.prism-dialog>footer {padding:16px;}.prism-calendar-popover {max-width:calc(100vw - 24px);}.prism-calendar {width:min(320px,calc(100vw - 26px));}.prism-calendar .rdp-month,.prism-calendar .rdp-month_grid {width:100%;}.prism-admin-header,.prism-admin-toolbar {flex-wrap:wrap;}.prism-admin-body {padding:16px;}}
.prism-candidate-card {position:relative;container-type:inline-size;word-break:break-word;}
.prism-candidate-header>.prism-favorite-toggle {position:absolute;right:0;top:0;z-index:2;}
.prism-candidate-name {padding-right:24px;min-width:0;}
.prism-candidate-label {min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:16px;font-weight:700;line-height:1.6;}
.prism-candidate-open {position:absolute;inset:0;padding:0;border:0;background:transparent;cursor:pointer;z-index:1;border-radius:12px;}
.prism-candidate-open:focus-visible {outline:2px solid var(--prism-blue-300);outline-offset:2px;}
.prism-candidate-extra {position:relative;z-index:2;}
.prism-candidate-card button:not(.prism-candidate-open),.prism-candidate-card a {position:relative;z-index:2;}
.prism-candidate-card .prism-candidate-header>.prism-favorite-toggle {position:absolute;right:0;top:0;}
.prism-candidate-categories {display:flex;flex-wrap:wrap;gap:0;font-size:12px;font-weight:500;line-height:1.4;color:#363636;}
.prism-candidate-categories>b:not(:last-child)::after {content:"";display:inline-block;width:1px;height:10px;background:var(--prism-control-border);margin:0 6px;}
.prism-candidate-brief {display:flex;flex-direction:column;gap:10px;background:#fff;padding:12px;border-radius:8px;}
.prism-candidate-brief>div {display:flex;align-items:flex-start;gap:2px;}
.prism-candidate-brief dt {flex:0 0 80px;color:var(--foreground);font-size:12px;font-weight:600;line-height:1.4;}
.prism-candidate-brief dd {flex:1;min-width:0;color:#363636;font-size:12px;font-weight:400;line-height:1.4;}
.prism-candidate-brief dt>small {display:block;font-size:10px;font-weight:400;color:var(--prism-sub);}
.prism-candidate-brief>hr {width:100%;margin:0;border:0;border-top:1px solid var(--prism-border);}
.prism-candidate-detail-button {display:flex;align-items:center;justify-content:center;gap:4px;line-height:1.4;}
.prism-candidate-card[data-panel] .prism-candidate-header {min-height:104px;flex-direction:row;}
.prism-candidate-profiles {container:prism-candidates / inline-size;display:grid;gap:10px;min-width:0;}
.prism-candidate-profiles-grid {display:grid;grid-template-columns:minmax(0,1fr);gap:10px;min-width:0;}
.prism-candidate-profiles[data-variant="pair"] .prism-candidate-profiles-grid {grid-template-columns:repeat(2,minmax(0,1fr));}
.prism-candidate-profiles[data-variant="grid"] .prism-candidate-profiles-grid {grid-template-columns:repeat(3,minmax(0,1fr));}
.prism-candidate-profiles-grid > * {min-width:0;}
.prism-candidate-profiles-more {justify-self:center;min-height:36px;padding:6px 16px;border:1px solid var(--prism-control-border);border-radius:8px;background:var(--surface);color:var(--foreground);font:inherit;cursor:pointer;}
.prism-candidate-profiles-more:focus-visible {outline:2px solid var(--prism-blue-300);outline-offset:2px;}
.prism-candidate-profiles-empty {margin:0;padding:16px;color:var(--prism-sub);text-align:center;}
.prism-candidate-assessment-table th:first-child {width:25%;}
.prism-candidate-assessment-table th,.prism-candidate-assessment-table td {overflow-wrap:anywhere;white-space:pre-line;}
.prism-candidate-assessment-detail {display:grid;justify-items:start;gap:4px;}
.prism-candidate-assessment-detail p {margin:0;white-space:pre-line;}
.prism-candidate-label {white-space:normal;overflow:visible;text-overflow:clip;overflow-wrap:anywhere;}
@container prism-candidates (max-width:800px) {.prism-candidate-profiles[data-variant="grid"] .prism-candidate-profiles-grid {grid-template-columns:repeat(2,minmax(0,1fr));}}
@container prism-candidates (max-width:560px) {.prism-candidate-profiles[data-variant="pair"] .prism-candidate-profiles-grid,.prism-candidate-profiles[data-variant="grid"] .prism-candidate-profiles-grid {grid-template-columns:minmax(0,1fr);}}
@container (max-width:260px) {.prism-candidate-brief>div {flex-direction:column;}.prism-candidate-brief dt {flex:none;}}
.prism-compensation,.prism-compensation-grid,.prism-leadership-trend,.prism-domain-profile-section,.prism-outline {min-width:0;max-width:100%;}
.prism-domain-profile-section {grid-template-columns:minmax(0,1fr);}
.prism-domain-profile-section>* {min-width:0;}

@media (max-width:480px) { .prism-admin-filter-bar { padding:16px; } .prism-admin-filter-actions { margin-left:auto; } }
